-- Atividades do guia do GitBook (favelaware.gitbook.io/favelaware) como atividades de
-- verdade nas turmas da Edição 4 (2027): o aluno lê a atividade no GitBook
-- (link_enunciado) e entrega no portal.
-- - 144 atividades em cada turma ("Turma 1" e "Turma 2"), sem prazo: a edição ainda
--   não tem datas; o professor define o prazo de cada uma depois.
-- - Enunciado = a descrição curta do GitBook.
-- - Sai da aba Materiais o link de cada atividade que a 20261001125000 colocou lá
--   (continua só o "Guia da trilha no GitBook"). Só apaga o que casa com url, título
--   e ordem daquela migration: material que a equipe cadastrou à mão fica.
-- Pode rodar mais de uma vez: atividade que a turma já tem (mesmo link) não entra de novo.
-- Se as duas turmas da Edição 4 não existirem com esses nomes, não faz nada (só avisa):
-- os links não saem da aba Materiais sem as atividades que os substituem.
-- Trilha que não existir com o nome esperado fica de fora, com aviso.

create temporary table atividades_do_gitbook (trilha text, titulo text, enunciado text, url text, ordem integer);


do $$
declare
  v_apagados integer;
  v_criadas integer;
  v_turmas integer;
  v_faltando text;
begin
  select count(*) into v_turmas
  from public.turmas tu
  join public.edicoes e on e.id = tu.edicao_id
  where e.nome = 'Edição 4 (2027)' and tu.nome in ('Turma 1', 'Turma 2');
  if v_turmas < 2 then
    raise warning 'Atividades do GitBook: achei % de 2 turmas da Edição 4 (2027); nada foi alterado', v_turmas;
    return;
  end if;

  delete from public.materiais m
  using atividades_do_gitbook v
  join public.trilhas t on t.nome = v.trilha
  where m.trilha_id = t.id and m.url = v.url and m.titulo = v.titulo and m.ordem = v.ordem;
  get diagnostics v_apagados = row_count;
  raise notice 'Atividades do GitBook: % links de atividade tirados da aba Materiais', v_apagados;

  select string_agg(distinct v.trilha, ', ') into v_faltando
  from atividades_do_gitbook v
  where not exists (select 1 from public.trilhas t where t.nome = v.trilha);
  if v_faltando is not null then
    raise warning 'Atividades do GitBook: trilhas não encontradas, ficaram sem atividades: %', v_faltando;
  end if;

  -- Na ordem do GitBook (turma, trilha, atividade): a tela desempata as sem prazo pelo id
  select tu.id, t.id, v.titulo, v.enunciado, v.url, null
  from atividades_do_gitbook v
  join public.trilhas t on t.nome = v.trilha
  cross join public.turmas tu
  join public.edicoes e on e.id = tu.edicao_id
  where e.nome = 'Edição 4 (2027)' and tu.nome in ('Turma 1', 'Turma 2')
    and not exists (
      select 1 from public.atividades a where a.turma_id = tu.id and a.link_enunciado = v.url
    )
  order by tu.id, t.ordem, v.ordem;
  get diagnostics v_criadas = row_count;
  raise notice 'Atividades do GitBook: % atividades criadas na Edição 4 (2027)', v_criadas;
end $$;

drop table atividades_do_gitbook;
